package com.emergency.patient.models;

import java.io.Serializable;

/**
 * DrPredictionResult — Encapsulates the inference outcome generated by the
 * NetraProof Diabetic Retinopathy Severity Prediction pipeline.
 *
 * Model Specifications:
 *  - Architecture: Five-fold EfficientNet-B0 ensemble.
 *  - Classification Method: Ordinal regression.
 *  - Predicted Output: ICDR 5-scale discrete severity grade (0 to 4).
 *
 * Clinical Distinction:
 *  - Strictly represents an assistive AI screening output, never a confirmed diagnosis.
 *  - Lesion segmentation is entirely independent and not part of this result model.
 */
public class DrPredictionResult implements Serializable {

    public enum PredictionState {
        INITIAL("Initial", "Ready to initialize DR severity evaluation."),
        PENDING("Prediction Pending", "Awaiting execution from the DR inference engine."),
        IN_PROGRESS("Analyzing Retinal Image", "Evaluating microvascular features with 5-fold EfficientNet-B0 ensemble..."),
        SUCCESS("AI Screening Complete", "Diabetic retinopathy severity classification completed successfully."),
        FAILED("Unable to Complete DR Screening", "The model inference pipeline encountered an error. Please retry."),
        SERVICE_UNAVAILABLE("Prediction Service Pending Integration", "The NetraProof EfficientNet-B0 ensemble inference service is pending server deployment. Downstream lesion segmentation remains locked.");

        private final String defaultTitle;
        private final String defaultDescription;

        PredictionState(String defaultTitle, String defaultDescription) {
            this.defaultTitle = defaultTitle;
            this.defaultDescription = defaultDescription;
        }

        public String getDefaultTitle() {
            return defaultTitle;
        }

        public String getDefaultDescription() {
            return defaultDescription;
        }
    }

    private String sessionId;
    private String patientUuid;
    private String imagePath;
    private String fileName;
    private int imageWidth;
    private int imageHeight;
    private long fileSizeBytes;
    private boolean qualityGatePassed = false;

    private PredictionState predictionState = PredictionState.INITIAL;
    private DrSeverityGrade predictedGrade = null;
    private Double modelScore = null; // Raw score/probability only if returned by verified backend
    private String modelVersion = "NetraProof-EfficientNet-B0-Ensemble-v1.0";
    private int ensembleFolds = 5;
    private String lossFunction = "Ordinal Regression";
    private long inferenceDurationMs = 0;
    private long assessmentTimestamp = 0;
    private String failureReason = null;

    public DrPredictionResult() {}

    /**
     * Determines whether downstream AI screening models (Lesion Segmentation)
     * are clinically unlocked.
     *
     * CLINICAL RULE: Downstream lesion segmentation is locked until an authoritative
     * DR severity prediction has succeeded and the quality gate is verified.
     */
    public boolean isDownstreamUnlocked() {
        return qualityGatePassed && predictionState == PredictionState.SUCCESS && predictedGrade != null;
    }

    // ─── Getters & Setters ────────────────────────────────────────────────────

    public String getSessionId() {
        return sessionId;
    }

    public void setSessionId(String sessionId) {
        this.sessionId = sessionId;
    }

    public String getPatientUuid() {
        return patientUuid;
    }

    public void setPatientUuid(String patientUuid) {
        this.patientUuid = patientUuid;
    }

    public String getImagePath() {
        return imagePath;
    }

    public void setImagePath(String imagePath) {
        this.imagePath = imagePath;
    }

    public String getFileName() {
        return fileName;
    }

    public void setFileName(String fileName) {
        this.fileName = fileName;
    }

    public int getImageWidth() {
        return imageWidth;
    }

    public void setImageWidth(int imageWidth) {
        this.imageWidth = imageWidth;
    }

    public int getImageHeight() {
        return imageHeight;
    }

    public void setImageHeight(int imageHeight) {
        this.imageHeight = imageHeight;
    }

    public long getFileSizeBytes() {
        return fileSizeBytes;
    }

    public void setFileSizeBytes(long fileSizeBytes) {
        this.fileSizeBytes = fileSizeBytes;
    }

    public boolean isQualityGatePassed() {
        return qualityGatePassed;
    }

    public void setQualityGatePassed(boolean qualityGatePassed) {
        this.qualityGatePassed = qualityGatePassed;
    }

    public PredictionState getPredictionState() {
        return predictionState;
    }

    public void setPredictionState(PredictionState predictionState) {
        this.predictionState = predictionState;
    }

    public DrSeverityGrade getPredictedGrade() {
        return predictedGrade;
    }

    public void setPredictedGrade(DrSeverityGrade predictedGrade) {
        this.predictedGrade = predictedGrade;
    }

    public Double getModelScore() {
        return modelScore;
    }

    public void setModelScore(Double modelScore) {
        this.modelScore = modelScore;
    }

    public String getModelVersion() {
        return modelVersion;
    }

    public void setModelVersion(String modelVersion) {
        this.modelVersion = modelVersion;
    }

    public int getEnsembleFolds() {
        return ensembleFolds;
    }

    public void setEnsembleFolds(int ensembleFolds) {
        this.ensembleFolds = ensembleFolds;
    }

    public String getLossFunction() {
        return lossFunction;
    }

    public void setLossFunction(String lossFunction) {
        this.lossFunction = lossFunction;
    }

    public long getInferenceDurationMs() {
        return inferenceDurationMs;
    }

    public void setInferenceDurationMs(long inferenceDurationMs) {
        this.inferenceDurationMs = inferenceDurationMs;
    }

    public long getAssessmentTimestamp() {
        return assessmentTimestamp;
    }

    public void setAssessmentTimestamp(long assessmentTimestamp) {
        this.assessmentTimestamp = assessmentTimestamp;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public void setFailureReason(String failureReason) {
        this.failureReason = failureReason;
    }
}

